@startuml

class GasStation {
  + ID : string
  + Address : string
}

class FuelPump {
  + Number : int
  + IsSelfService : boolean
}

class Fuel {
  + Name : string
  + OctaneRating : int
}

class DailyPrice {
  + Date : date
  + PricePerLiter : float
}

class FuelPurchase {
  + ID : string
  + LitersDispensed : float
}

GasStation "1" -- "1..12" FuelPump
FuelPump "*" -- "*" Fuel

GasStation "1" -- "*" DailyPrice
Fuel "1" -- "*" DailyPrice
GasStation "1" -- "*" DailyPrice : applies to

FuelPump "1" -- "*" FuelPurchase
DailyPrice "1" -- "*" FuelPurchase

@enduml

